import numpy as np

def master(frames):
    return np.median(np.stack(frames), axis=0)

def calibrate(raw, bias, dark, flat, t_sci=1.0, t_dark=1.0):
    flat_norm = flat / np.median(flat)
    return (raw - bias - dark * (t_sci / t_dark)) / flat_norm

import numpy as np
from scipy.ndimage import shift as ndshift

def align(frame, dy, dx):
    return ndshift(frame.astype(float), (dy, dx), order=3, mode='constant')

def combine(frames, weights=None):
    cube = np.stack(frames).astype(float)
    w = np.ones(len(cube)) if weights is None else np.asarray(weights, float)
    return np.tensordot(w / w.sum(), cube, axes=(0, 0))

from astropy.wcs import WCS
from astropy.coordinates import SkyCoord, match_coordinates_sky
import astropy.units as u

def detected_skycoords(header, x, y):
    w = WCS(header)
    ra, dec = w.all_pix2world(x, y, 0)
    return SkyCoord(ra * u.deg, dec * u.deg)

def match_catalog(det, cat, max_sep=2 * u.arcsec):
    idx, sep, _ = match_coordinates_sky(det, cat)
    return idx, sep < max_sep

import numpy as np

rng = np.random.default_rng(42)

def exp_samples(n, rate=2.0):
    return -np.log(1.0 - rng.random(n)) / rate

def normal_box_muller(n):
    u1, u2 = rng.random(n), rng.random(n)
    r = np.sqrt(-2.0 * np.log(u1))
    return r * np.cos(2 * np.pi * u2)
